import { Affix } from "@godxjp/ui/layout";
import { Button, Text } from "@godxjp/ui/general";
import { Flex } from "@godxjp/ui/layout";

const [pinned, setPinned] = useState(false);

<Affix offsetBlockStart={64} onChange={setPinned}>
  <Flex align="center" justify="between" gap="sm">
    <Text weight="medium">{pinned ? "Invoices" : "All invoices, 2026"}</Text>
    <Button size={pinned ? "sm" : "md"}>New invoice</Button>
  </Flex>
</Affix>
